const ALPHA = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ-_';
const cache = {};
export function portraitPic(k) {
  if (cache[k]) return cache[k];
  const d = PORTRAITS[k]; if (!d) return null;
  const pal = d.p.split('.').map(h => '#' + h);
  return cache[k] = { w: 24, h: 32, rgb: [...d.x].map(c => pal[ALPHA.indexOf(c)]) };
}
